/* v1271 LANGUAGES step 2 (tester 4 Nov: "the skill descriptions still are English only") - game CONTENT (skill, passive, ultimate text ...)
   lives in lang/<code>.content.json, fetched only for that language at ?v=<its hash> (EW_LANG_CV). It maps an English sentence with its
   numbers taken out ({0}, {1} ... in order) to the translation, so one entry serves every skill level; icon tokens {i:..}, tags and
   entities stay as written. langDesc(s) returns the player's language, or s itself when no entry exists - English is never lost.
   LANG.collect (a Set, set by tools/lang/collect_content.js) gathers every template the game produces. */
const LANG_TPL_RE=/\{[^{}]*\}|<[^>]*>|&#?\w+;|\d+(?:\.\d+)?/g;
function langTpl(s){ const nums=[]; const k=String(s).replace(LANG_TPL_RE,m=>{ if(m[0]==='{'||m[0]==='<'||m[0]==='&') return m; nums.push(m); return '{'+(nums.length-1)+'}'; }); return {k,nums}; }
function langDesc(s){ if(s==null||s==='') return s; s=String(s); if(LANG.collect) LANG.collect.add(langTpl(s).k);
  if(LANG.cur==='en'||!LANG.content) return s; const p=langTpl(s), v=LANG.content[p.k]; if(LANG.cur==='qps') return v?'⟦'+s+'⟧':s;
  return (typeof v==='string'&&v)?v.replace(/\{(\d+)\}/g,(m,i)=>p.nums[i]!=null?p.nums[i]:m):s; }
function langMeta(m){ if(!m) return m; const pre=' — '; if(m.indexOf(pre)!==0) return langDesc(m); return pre+m.slice(pre.length).split(' · ').map(langDesc).join(' · '); }
function langContentLoad(code){ LANG.content=null; const v=EW_LANG_CV[code]; if(code==='en'||!v) return;   // kept like the dictionary (ew_lang_content): the next open needs no fetch
  try{ const c=JSON.parse(localStorage.getItem('ew_lang_content')||'null'); if(c&&c.code===code&&c.v===v&&c.d&&typeof c.d==='object'){ LANG.content=c.d; return; } }catch(e){}
  try{ fetch('/lang/'+(code==='qps'?'en-XA':code)+'.content.json?v='+v).then(r=>r.ok?r.json():null).then(d=>{ if(!d||typeof d!=='object'||LANG.cur!==code) return; LANG.content=d;
    try{ localStorage.setItem('ew_lang_content',JSON.stringify({code,v,d})); }catch(e){} langRefresh(true); }).catch(()=>{}); }catch(e){} }
